/// Descrittore di rwlock
struct des_rw {
	/// id del processo che possiede il write lock (0 se nessuno) 
	natl writer;
	/// numero dei processi che possiedono un read lock
	natl nreaders;
	/// processi in attesa di acquisire un read lock
	des_proc* w_readers;
	/// processi in attesa di acquisire il write lock
	des_proc* w_writers;
};

/// Array dei descrittori di rwlock
des_rw array_desrw[MAX_RW];
/// Numero di rwlock allocati
natl rw_allocati = 0;

/**
 * @brief Alloca un nuovo descrittore di rwlock.
 *
 * @return id del rwlock, 0xFFFFFFFF in caso di errore
 */
natl alloca_rw()
{
	natl i;

	if (rw_allocati >= MAX_RW)
		return 0xFFFFFFFF;

	i = rw_allocati;
	rw_allocati++;
	return i;
}

/**
 * @brief Controlla la validità di un id di rwlock.
 *
 * @param rw id da controllare
 *
 * @return  true se l'id corrisponde ad un rwlock allocato, false altrimenti
 */
bool rw_valido(natl rw)
{
	return rw < rw_allocati;
}

/// Parte C++ della primitiva rw_init()
extern "C" natl c_rw_init()
{
	natl rw = alloca_rw();

	if (rw == 0xFFFFFFFF)
		return 0xFFFFFFFF;

	des_rw *r = &array_desrw[rw];

	r->nreaders = 0;
	r->writer = 0;
	r->w_readers = nullptr;
	r->w_writers = nullptr;
	return rw;
}

/**
 * @brief Trova il des_proc_rw associato ad un dato rwlock per un dato processo
 *
 * @note se r è nullptr si può usare per trovare un descrittore libero
 *
 * @param r	descrittore di rwlock o nullptr
 * @param p	processo 
 *
 * @return puntatore al descrittore, o nullptr se non trovato
 */
static des_proc_rw *rw_proc_find(des_rw *r = nullptr, des_proc *p = esecuzione)
{
	for (int i = 0; i < MAX_PROC_RW; i++) {
		des_proc_rw *rp = &p->rws[i];
		if (rp->r == r)
			return rp;
	}
	return nullptr;
}

/// Parte C++ della primitiva rw_writelock()
extern "C" void c_rw_writelock(natl rw)
{
	if (!rw_valido(rw)) {
		flog(LOG_WARN, "rw_writelock(%d): rwlock non valido", rw);
		c_abort_p();
		return;
	}

	des_rw *r = &array_desrw[rw];
	des_proc_rw *rp;

	if (rw_proc_find(r)) {
		flog(LOG_WARN, "rw_writelock(%d): rwlock gia' attivo", rw);
		c_abort_p();
		return;
	}

	rp = rw_proc_find();
	if (!rp) {
		esecuzione->contesto[I_RAX] = false;
		return;
	}
	rp->r = r;

	esecuzione->contesto[I_RAX] = true;
	if (r->nreaders > 0 || r->writer) {
		rp->state = RW_NONE;
		inserimento_lista(r->w_writers, esecuzione);
		schedulatore();
	} else {
		rp->state = RW_WRITER;
		r->writer = esecuzione->id;
	}
}

/// Parte C++ della primitiva rw_readlock()
extern "C" void c_rw_readlock(natl rw)
{
	if (!rw_valido(rw)) {
		flog(LOG_WARN, "rw_readlock(%d): rwlock non valido", rw);
		c_abort_p();
		return;
	}

	des_rw *r = &array_desrw[rw];
	des_proc_rw *rp;

	if (rw_proc_find(r)) {
		flog(LOG_WARN, "rw_readlock(%d): rwlock gia' attivo", rw);
		c_abort_p();
		return;
	}

	rp = rw_proc_find();
	if (!rp) {
		esecuzione->contesto[I_RAX] = false;
		return;
	}
	rp->r = r;

	esecuzione->contesto[I_RAX] = true;
	if (r->writer) {
		rp->state = RW_NONE;
		inserimento_lista(r->w_readers, esecuzione);
		schedulatore();
	} else {
		rp->state = RW_READER;
		r->nreaders++;
	}
}
